import { sql } from 'drizzle-orm';
import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';

/** Raw bytes; holds SHA-256 digests of tokens, never the tokens themselves. */
export const bytea = customType<{ data: Uint8Array; driverData: Buffer }>({
  dataType: () => 'bytea',
  toDriver: (value) => Buffer.from(value),
  fromDriver: (value) => new Uint8Array(value),
});

/** UUIDv7 (time-ordered) primary key, generated by PostgreSQL 18. */
export const id = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

/** An instant: timestamptz, read as a Date. */
export const at = () => timestamp({ withTimezone: true });

export const createdAt = () => at().notNull().defaultNow();
